(function(){'use strict';const KEY='ink-mode';const root=document.documentElement;const media=window.matchMedia('(prefers-color-scheme: dark)');const VALID=['light','dark','auto'];function fromUrl(){try{const value=(new URLSearchParams(location.search).get('mode')||'').toLowerCase();return VALID.includes(value)?value:'';}catch(e){return'';}}
function readPref(){const fromQuery=fromUrl();if(fromQuery)return fromQuery;try{return localStorage.getItem(KEY)||root.getAttribute('data-mode-pref')||'auto';}
catch(e){return'auto';}}
function resolve(pref){return pref==='dark'||(pref==='auto'&&media.matches);}
function apply(pref,persist){const dark=resolve(pref);root.setAttribute('data-mode',dark?'dark':'light');root.setAttribute('data-mode-pref',pref);if(persist&&!fromUrl()){try{localStorage.setItem(KEY,pref);}catch(e){}}
document.querySelectorAll('[data-mode-set]').forEach((btn)=>{btn.setAttribute('aria-checked',String(btn.getAttribute('data-mode-set')===pref));});const meta=document.querySelector('meta[name="theme-color"]:not([media])');if(meta){meta.setAttribute('content',dark?getComputedStyle(root).getPropertyValue('--paper').trim()||'#121110':getComputedStyle(root).getPropertyValue('--paper').trim()||'#f6f2e8');}
document.dispatchEvent(new CustomEvent('ink:mode',{detail:{mode:dark?'dark':'light',pref}}));}
document.addEventListener('DOMContentLoaded',()=>{const pref=readPref();apply(pref,false);document.querySelectorAll('[data-mode-set]').forEach((btn)=>{btn.addEventListener('click',()=>{apply(btn.getAttribute('data-mode-set'),true);document.querySelectorAll('.menu').forEach((m)=>{m.hidden=true;});});});const onSystemChange=()=>{if(readPref()==='auto')apply('auto',false);};if(media.addEventListener)media.addEventListener('change',onSystemChange);else if(media.addListener)media.addListener(onSystemChange);});window.InkMode={get:readPref,set:apply};})();